# Code generated by Claude
"""
Tests of the gripper force limit (the "max_force" of a gripper command).

    MUJOCO_GL=egl python experiments/gripper_force_test.py

1. validate_command: a gripper entry may be a travel or {"position", "max_force"}; max_force <= 0 or not finite is rejected, above the hardware ceiling
   (10 N per finger) it is clipped, omitted it is the ceiling.
2. The beaker held between the fingers: the arm goes to the grasp pose (the open fingers straddle the beaker) and the gripper is commanded closed three times
   with max_force 1 N, 2 N and none (the ceiling), opening in between. For each, the finger-on-beaker normal force (MuJoCo contact forces) settles at the limit
   (or, for the ceiling, at what the servo itself gives: kp times the finger's distance from the commanded 0).
3. The episode is recorded; max_force changes mid-run. Its replay must be bit-identical.
"""

import os
import shutil
import sys
import tempfile
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

from src import robot_specs  # noqa: E402
from src.commands import validate_command  # noqa: E402
from src.episode_runner import run_episode  # noqa: E402
from src.episode_test_sources import make_grasp_force_stage  # noqa: E402
from src.replay import replay_run  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import EPISODE_CFG  # noqa: E402

results = []
BEAKER_KG = 0.15


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def unit():
    print("\nvalidate_command")
    ceil = robot_specs.ARM_ACTUATOR_SPECS["fingers"]["force_limit"]
    lim = {"gripper": (0.0, 0.044), "gripper_force_ceiling": ceil}
    v = lambda g: validate_command({"mode": "arms", "gripper": {"left": g}}, lim)
    c, _ = v(0.02)
    check("a plain travel: the ceiling", c["gripper"]["left"] == 0.02 and c["gripper_force"]["left"] == ceil, str(c))
    c, _ = v({"position": 0.0, "max_force": 2.0})
    check("position and max_force", c["gripper"]["left"] == 0.0 and c["gripper_force"]["left"] == 2.0)
    c, _ = v({"position": 0.01})
    check("a dict without max_force: the ceiling", c["gripper_force"]["left"] == ceil)
    c, msgs = v({"position": 0.0, "max_force": 50.0})
    check("above the ceiling: clipped (with a message)", c["gripper_force"]["left"] == ceil and msgs, str(msgs))
    for bad in (0.0, -1.0, float("nan"), float("inf"), "x"):
        c, msgs = v({"position": 0.0, "max_force": bad})
        check(f"max_force {bad!r} is rejected", c is None, str(msgs))
    c, msgs = v({"max_force": 1.0})
    check("a dict without position is rejected", c is None)
    c, _ = validate_command({"mode": "arms", "arm_targets": {"left": [0.0] * 7}}, lim)
    check("an arms command without a gripper entry carries no force (the limit is left alone)", "gripper_force" not in c)


def grasp():
    print("\nbeaker between the fingers, closed at max_force 1 N, 2 N and the ceiling")
    sim = load_task(cameras=True)
    stage = {}

    def make(m, d):
        stage["s"] = make_grasp_force_stage(m, d)
        return stage["s"]

    out = Path(tempfile.mkdtemp(prefix="gripper_force_"))
    s = run_episode(make, sim.model, sim.data, episode_cfg={**EPISODE_CFG, "timeout_after_handoff": 25.0}, out_dir=out / "episode", record_dir=out / "recording")
    res = stage["s"]["state"]["results"]
    check("three closings measured", len(res) == 3, f"{len(res)}")
    kp = robot_specs.ARM_ACTUATOR_SPECS["fingers"]["kp"]
    for r in res:
        F = r["max_force_command"]
        cap = r["applied_cap"]
        print(f"    max_force {'ceiling' if F is None else str(F) + ' N'}: applied cap {cap:.2f} N, force of each finger on the beaker along the closing axis {np.round(r['contact_normal_N_per_finger_mean'], 3)} N "
              f"(peak {r['contact_normal_N_peak']:.3f} N; sum of the contacts' normal magnitudes {np.round(r['contact_normal_sum_N_per_finger_mean'], 3)} N), finger actuator force {np.round(r['actuator_force_N_mean'], 3)} N, fingers at {np.round(r['finger_q_mm'], 1)} mm, "
              f"{r['n_fingers_in_contact']} fingers in contact")
        check(f"closing {F}: both fingers touch the beaker", r["n_fingers_in_contact"] == 2)
        limit = cap
        check(f"closing {F}: each finger actuator applies at most the limit ({limit:.2f} N)", all(f <= limit + 1e-6 for f in r["actuator_force_N_mean"]), f"{np.round(r['actuator_force_N_mean'], 4)} N")
        cf = r["contact_normal_N_per_finger_mean"]
        weight_axial = BEAKER_KG * 9.81 * abs(r["closing_axis_z"])        # the beaker's weight along the (slightly tilted) closing axis loads one finger and unloads the other
        check(f"closing {F}: each finger's contact force is the limit within the beaker's weight along the closing axis (+-{weight_axial:.2f} N)",
              all(abs(f - limit) <= weight_axial + 0.02 for f in cf) if F is not None else all(abs(f - r["actuator_force_N_mean"][0]) <= weight_axial + 0.02 for f in cf), f"{np.round(cf, 3)} N")
        check(f"closing {F}: the two fingers' mean contact force is the limit (within 3%)" if F is not None else "closing at the ceiling: the mean contact force equals the servo's own force (within 3%)",
              abs(np.mean(cf) - (limit if F is not None else np.mean(r["actuator_force_N_mean"]))) <= 0.03 * (limit if F is not None else np.mean(r["actuator_force_N_mean"])), f"mean {np.mean(cf):.3f} N")
        if F is not None:
            check(f"closing {F}: and the limit binds (the actuators sit at it)", all(abs(f - limit) < 1e-3 for f in r["actuator_force_N_mean"]))
        else:
            e = np.mean(r["finger_q_mm"]) / 1000
            check("closing at the ceiling: the servo's own force, kp * (distance to the commanded 0), is below the 10 N ceiling",
                  all(abs(f - kp * e) < 0.05 * kp * e for f in r["actuator_force_N_mean"]) and kp * e < 10.0, f"kp * q = {kp * e:.2f} N")
    print("\nreplay of the recording (the limit changes mid-run: 10 -> 1 -> 10 -> 2 -> 10 -> ceiling)")
    rep = replay_run(out / "recording", video="none", quiet=True)
    check("the replay is bit-identical", rep["ok"], f"{rep['ticks']} ticks, mismatch {rep['mismatch']}")
    import json
    meta = json.loads((out / "recording" / "meta.json").read_text())
    from src.run_record import load_recording
    rec = load_recording(out / "recording")
    changes = sorted({tuple(np.round(row, 3)) for row in rec["gripforce"]})
    check("the recording holds the applied limits", rec["gripforce"] is not None and len(changes) >= 3, f"distinct (left, right) limits: {changes}")
    shutil.rmtree(out, ignore_errors=True)


if __name__ == "__main__":
    unit()
    grasp()
    print(f"\n{sum(results)}/{len(results)} checks passed")
    sys.exit(0 if all(results) else 1)
